# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">RAFADAN TAYFA - İSTİKLÂL MARŞI: DİNLEME/İZLEME VE MİLLÎ DEĞERLER</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">İstiklâl Marşı ve Tarihî Arka Plan</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11" fill="#7f1d1d">• Millî Şairimiz: Mehmet Âkif Ersoy</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11" fill="#7f1d1d">• Yazıldığı Yer: Ankara - Taceddin Dergâhı</text>\n  <text x="180" y="142" text-anchor="middle" font-size="11" fill="#7f1d1d">• Kabul Tarihi: 12 Mart 1921 (TBMM)</text>\n  <text x="180" y="164" text-anchor="middle" font-size="11" fill="#7f1d1d">• İthaf: Kahraman Ordumuza armağan edildi</text>\n  <text x="180" y="186" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">• Para ödülünü Darülmesai\'ye bağışladı:</text>\n  <text x="180" y="206" text-anchor="middle" font-size="10.5" fill="#475569">«Allah bu millete bir daha İstiklâl Marşı yazdırmasın!»</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Görsel ve İşitsel Unsurları Yorumlama</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11" fill="#1e3a8a">• Tahmin Etme (T.D.6.3): Başlık ve görselden</text>\n  <text x="520" y="116" text-anchor="middle" font-size="11" fill="#1e3a8a">hareketle içerik hakkında öngörüde bulunma</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" fill="#1e3a8a">• Çıkarım ve Sınıflandırma (T.D.6.7/11):</text>\n  <text x="520" y="156" text-anchor="middle" font-size="11" fill="#1e3a8a">Ses tonu, vurgu, müzik ve yüz ifadelerinden</text>\n  <text x="520" y="174" text-anchor="middle" font-size="11" fill="#1e3a8a">duygu ve örtük mesajları belirleme</text>\n  <text x="520" y="202" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Değerler: Vatanseverlik, Özgürlük, Saygı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSİM TAMLAMALARI: BELİRTİLİ, BELİRTİSİZ VE ZİNCİRLEME</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">1. Belirtili İsim Tamlaması</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11" fill="#14532d">• Tamlayan eki (-ın/-in/-nın) VAR</text>\n  <text x="125" y="118" text-anchor="middle" font-size="11" fill="#14532d">• Tamlanan eki (-ı/-i/-sı/-si) VAR</text>\n  <text x="125" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Soru: Neyin / Kimin ...?</text>\n  <text x="125" y="168" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">• millet-in bağımsızlığ-ı</text>\n  <text x="125" y="188" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">• bayrağ-ın gölge-si</text>\n  <text x="125" y="208" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">• şair-in vatan sevgi-si</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">2. Belirtisiz İsim Tamlaması</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11" fill="#713f12">• Tamlayan eki YOK (Yalın hâlde)</text>\n  <text x="350" y="118" text-anchor="middle" font-size="11" fill="#713f12">• Tamlanan eki (-ı/-i/-sı/-si) VAR</text>\n  <text x="350" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">Soru: Ne ...?</text>\n  <text x="350" y="168" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#854d0e">• İstiklâl Marş-ı</text>\n  <text x="350" y="188" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#854d0e">• bağımsızlık yol-u</text>\n  <text x="350" y="208" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#854d0e">• vatan topraklar-ı</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">3. Zincirleme İsim Tamlaması</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11" fill="#581c87">• En az ÜÇ İSMİN birbirine</text>\n  <text x="575" y="116" text-anchor="middle" font-size="11" fill="#581c87">aitlik ekiyle bağlanmasıdır.</text>\n  <text x="575" y="140" text-anchor="middle" font-size="11" fill="#581c87">• İçinde birden fazla isim</text>\n  <text x="575" y="158" text-anchor="middle" font-size="11" fill="#581c87">tamlaması barındırır (sıfat değil!):</text>\n  <text x="575" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">• İstiklâl Marşı\'nın kabul günü</text>\n  <text x="575" y="206" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">• Türk milletinin zafer sevinci</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ZAMİRLER (ADILLAR): SÖZCÜK VE EK HÂLİNDEKİ ZAMİRLER</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">1. Sözcük Hâlindeki Zamirler</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">• Kişi (Şahıs): ben, sen, o, biz, siz, onlar</text>\n  <text x="180" y="116" text-anchor="middle" font-size="10.5" fill="#334155">(Dönüşlülük zamiri: «kendi» ➔ kendim, kendisi)</text>\n  <text x="180" y="140" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">• İşaret: bu, şu, o, bunlar, şunlar, onlar, burası</text>\n  <text x="180" y="162" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">• Belgisiz: herkes, kimse, bazıları, biri, hepsi</text>\n  <text x="180" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">• Soru: kim, ne, hangisi, nereye, kaçı?</text>\n  <text x="180" y="210" text-anchor="middle" font-size="10.5" fill="#0f172a">Dikkat: «O şiiri okudu» (Zamir) ≠ «O şiir güzeldi» (Sıfat)</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">2. Ek Hâlindeki Zamirler</text>\n  <text x="520" y="100" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">• İyelik (Aitlik) Zamirleri (-ım, -ın, -ı, -ımız...):</text>\n  <text x="520" y="120" text-anchor="middle" font-size="11" fill="#475569">İsme gelerek kime ait olduğunu bildirir:</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#7c2d12">yurd-um, bayrağ-ın, vatan-ımız, marş-ları</text>\n  <text x="520" y="166" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">• İlgi Zamiri (-ki):</text>\n  <text x="520" y="186" text-anchor="middle" font-size="11" fill="#475569">Tamlanan ismin yerini tutar (-ınki / -imki):</text>\n  <text x="520" y="206" text-anchor="middle" font-size="11" font-weight="bold" fill="#7c2d12">«Benim şiirim bitti, seninki (senin şiirin) kaldı.»</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
